def is_valid(sigma_k, sigma_next_k):
    k = len(sigma_k) - 1
    # Condition 1: sigma_next_k(x_1+1) > sigma_next_k(x_2+1) if sigma_k(x_1) > sigma_k(x_2)
    for x1 in range(k + 1):
        for x2 in range(k + 1):
            if sigma_k[x1] > sigma_k[x2]:
                if not (sigma_next_k[x1+1] > sigma_next_k[x2+1]):
                    return False
    # Condition 2: sigma_next_k(x_1) > sigma_next_k(x_2) if sigma_k(x_1) > sigma_k(x_2)
    for x1 in range(k + 1):
        for x2 in range(k + 1):
            if sigma_k[x1] > sigma_k[x2]:
                if not (sigma_next_k[x1] > sigma_next_k[x2]):
                    return False
    return True

def find_all_valid_sigma(k):
    import itertools
    perms = list(itertools.permutations(range(k + 1)))
    valid_perms = []
    for p in perms:
        valid_perms.append(p)
    return valid_perms

# Let's find all valid sigma_k
# We start with sigma_0 = (0,)
# Then we find all sigma_1 that are valid for sigma_0
# Then all sigma_2 that are valid for sigma_1, and so on.

valid_sigma = {0: [(0,)]}
for k in range(0, 5): # Check up to k=5
    current_level = valid_sigma[k]
    next_level = []
    import itertools
    for sigma_k in current_level:
        for sigma_next_k in itertools.permutations(range(k + 2)):
            if is_valid(sigma_k, sigma_next_k):
                next_level.append(sigma_next_k)
    valid_sigma[k+1] = next_level

for k in range(6):
    print(f"k={k}: {len(valid_sigma[k])} valid sigma")
    for s in valid_sigma[k]:
        print(s)

def h(n):
    return n * (n + 1) // 2

def f1(x, y):
    return h(x + y) + x

def f2(x, y):
    return h(x + y) + y

N1 = 0
for x in range(100):
    for y in range(100):
        if f1(x, y) % 2 != 0:
            N1 += 1

N2 = 0
for x in range(100):
    for y in range(100):
        if f2(x, y) % 2 != 0:
            N2 += 1

print(f"N1: {N1}")
print(f"N2: {N2}")

def solve():
    n_total = 0
    # f(x, y) = h(x+y) + x
    # h(n) = n*(n+1)//2
    # We want f(x, y) % 2 != 0
    for x in range(100):
        for y in range(100):
            n = x + y
            h_n = n * (n + 1) // 2
            if (h_n + x) % 2 != 0:
                n_total += 1
    return n_total

print(solve())

def get_N(f_type):
    count = 0
    for x in range(100):
        for y in range(100):
            if f_type == 1:
                val = (x + y) * (x + y + 1) // 2 + x
            else:
                val = (x + y) * (x + y + 1) // 2 + y
            if val % 2 != 0:
                count += 1
    return count

